using System;

// Fictional Lantern Cafe: two lunches, a sample tax, and a tip.
var quote = Quote(1299, 2, 750, 400);
Check(quote.Subtotal == 2598, "Two lunches cost 2598 cents.");
Check(quote.Tax == 195, "The sample tax rounds to 195 cents.");
Check(quote.Total == 3193, "Total includes subtotal, tax, and tip.");
Check(Quote(10, 1, 500, 0).Tax == 1, "Half a cent rounds away from zero.");
Check(Quote(100, 1, 0, 0).Total == 100, "Zero tax and tip add nothing.");

Console.WriteLine($"Subtotal: {quote.Subtotal} cents");
Console.WriteLine($"Tax: {quote.Tax} cents; tip: 400 cents");
Console.WriteLine($"Total: {quote.Total} cents");
Console.WriteLine("PASS: money");

static (int Subtotal, int Tax, int Total) Quote(
    int unitCents, int quantity, int taxBasisPoints, int tipCents)
{
    if (unitCents < 0 || quantity is < 1 or > 20 ||
        taxBasisPoints is < 0 or > 2500 || tipCents < 0)
        throw new ArgumentOutOfRangeException("Use valid sample inputs.");
    int subtotal = checked(unitCents * quantity);
    int tax = checked((int)decimal.Round(
        subtotal * (decimal)taxBasisPoints / 10000m,
        0, MidpointRounding.AwayFromZero));
    int total = checked(subtotal + tax + tipCents);
    return (subtotal, tax, total);
}

static void Check(bool condition, string message)
{
    if (!condition) throw new Exception("FAIL: " + message);
}

using System;
using System.Collections.Generic;

// Fictional Harbor Kitchen pickup request; no order is saved.
Check(Validate("Avery", 1).Count == 0, "Quantity 1 is allowed.");
Check(Validate("Avery", 20).Count == 0, "Quantity 20 is allowed.");
Check(Validate("Avery", 0).Contains("Choose 1 to 20 items."), "Zero is rejected.");
Check(Validate("Avery", 21).Contains("Choose 1 to 20 items."), "21 is rejected.");
Check(Validate(null, 1).Count == 1, "A missing name is rejected.");
Check(Validate("   ", 1).Count == 1, "A blank name is rejected.");
Check(Validate(new string('x', 41), 1).Count == 1, "A long name is rejected.");
Check(Validate(" Avery ", 2).Count == 0, "Surrounding spaces are accepted.");
var problems = Validate("", 0);
Check(problems.Count == 2, "Report both independent problems.");
foreach (string problem in problems) Console.WriteLine(problem);
Console.WriteLine("PASS: validation");

static List<string> Validate(string? name, int quantity)
{
    var problems = new List<string>();
    string cleanedName = (name ?? "").Trim();
    if (cleanedName.Length is < 1 or > 40)
        problems.Add("Enter a name from 1 to 40 characters.");
    if (quantity < 1 || quantity > 20)
        problems.Add("Choose 1 to 20 items.");
    return problems;
}

static void Check(bool condition, string message)
{
    if (!condition) throw new Exception("FAIL: " + message);
}

using System;

// Fictional Cove Diner menu snapshots, held only in memory.
var original = new MenuItem("soup", "Garden soup", 900, true);
var weekend = original with { PriceCents = 950 };
var soldOut = weekend with { Available = false };
var sameValues = new MenuItem("soup", "Garden soup", 900, true);

Check(original.PriceCents == 900, "The original price stays unchanged.");
Check(weekend.PriceCents == 950, "The copied price is 950 cents.");
Check(weekend.Id == original.Id, "The item identity stays the same.");
Check(weekend.Name == original.Name, "The name is copied.");
Check(original == sameValues, "Records compare their values.");
Check(original != weekend, "A changed price makes unequal values.");
Check(!ReferenceEquals(original, weekend), "with creates a different object.");
Check(!soldOut.Available && weekend.Available, "Only the sold-out copy changes.");
Check(soldOut.PriceCents == 950, "A later copy keeps the changed price.");

Console.WriteLine($"Original: {original.Name}, {original.PriceCents} cents");
Console.WriteLine($"Weekend: {weekend.Name}, {weekend.PriceCents} cents");
Console.WriteLine($"Sold-out copy available: {soldOut.Available}");
Console.WriteLine("PASS: records");

static void Check(bool condition, string message)
{
    if (!condition) throw new Exception("FAIL: " + message);
}

sealed record MenuItem(string Id, string Name, int PriceCents, bool Available);

using System;
using System.Collections.Generic;
using System.Linq;

// Fictional data only. The caller here is not authenticated.
var orders = new List<Order>
{
    new("lantern-cafe", "order-1", 1200),
    new("harbor-kitchen", "order-1", 900)
};

var lantern = FindOrder(orders, "lantern-cafe", "order-1");
var harbor = FindOrder(orders, "harbor-kitchen", "order-1");
Check(lantern?.TotalCents == 1200, "Lantern receives its own order.");
Check(harbor?.TotalCents == 900, "Harbor receives its own order.");
Check(FindOrder(orders, "unknown-cafe", "order-1") is null,
    "An unknown tenant receives no order.");
Check(FindOrder(orders, "lantern-cafe", "missing") is null,
    "A missing order receives no result.");
Check(FindOrder(orders, "", "order-1") is null,
    "A missing tenant cannot broaden the lookup.");

Console.WriteLine($"Lantern order: {lantern!.TotalCents} cents");
Console.WriteLine($"Harbor order: {harbor!.TotalCents} cents");
Console.WriteLine("PASS: tenants");

static Order? FindOrder(IEnumerable<Order> orders, string tenantId, string orderId)
{
    if (string.IsNullOrWhiteSpace(tenantId) || string.IsNullOrWhiteSpace(orderId))
        return null;
    return orders.FirstOrDefault(o => o.TenantId == tenantId && o.Id == orderId);
}

static void Check(bool condition, string message)
{
    if (!condition) throw new Exception("FAIL: " + message);
}

sealed record Order(string TenantId, string Id, int TotalCents);

using System;
using System.Collections.Generic;

// Fictional orders only. This single-process ledger is not durable.
var ledger = new Dictionary<(string Tenant, string Key), (Request Body, Receipt Result)>();
var request = new Request("soup", 1);
var first = Submit("lantern-cafe", "attempt-1", request);
var retry = Submit("lantern-cafe", "attempt-1", request);
Check(first == retry, "An identical retry returns the original receipt.");
Check(ledger.Count == 1, "An identical retry does not create a second order.");

bool conflict = false;
try { Submit("lantern-cafe", "attempt-1", request with { Quantity = 2 }); }
catch (InvalidOperationException) { conflict = true; }
Check(conflict, "Changed details with the same key must be rejected.");
Check(ledger.Count == 1, "A rejected request creates no order.");
Check(Submit("lantern-cafe", "attempt-1", request) == first,
    "A conflict cannot overwrite the original receipt.");

var other = Submit("harbor-kitchen", "attempt-1", request);
Check(other != first, "Another tenant has a separate request key.");
Check(ledger.Count == 2, "Exactly two fictional orders exist.");
Console.WriteLine($"First receipt: {first.OrderId}");
Console.WriteLine($"Retry receipt: {retry.OrderId}");
Console.WriteLine($"Stored orders: {ledger.Count}");
Console.WriteLine("PASS: retries");

Receipt Submit(string tenant, string key, Request body)
{
    if (string.IsNullOrWhiteSpace(tenant) || string.IsNullOrWhiteSpace(key) ||
        string.IsNullOrWhiteSpace(body.ItemId) || body.Quantity is < 1 or > 20)
        throw new ArgumentException("Use valid fictional order inputs.");
    if (ledger.TryGetValue((tenant, key), out var existing))
    {
        if (existing.Body != body)
            throw new InvalidOperationException("Request key has different details.");
        return existing.Result;
    }
    var receipt = new Receipt($"order-{ledger.Count + 1}", tenant, body.Quantity);
    ledger.Add((tenant, key), (body, receipt));
    return receipt;
}

static void Check(bool condition, string message)
{
    if (!condition) throw new Exception("FAIL: " + message);
}

sealed record Request(string ItemId, int Quantity);
sealed record Receipt(string OrderId, string TenantId, int Quantity);
